class Solution {
  public int minDeletionSize(String[] strs) {
    int m = strs[0].length(), best = 0;
    int[] dp = new int[m];
    for (int j = 0; j < m; j++) {
      dp[j] = 1;
      for (int i = 0; i < j; i++) {
        boolean ok = true;
        for (String s : strs)
          if (s.charAt(i) > s.charAt(j)) {
            ok = false;
            break;
          }
        if (ok) dp[j] = Math.max(dp[j], dp[i] + 1);
      }
      best = Math.max(best, dp[j]);
    }
    return m - best;
  }
}
